from pathlib import Path
import json
r=Path(__file__).resolve().parent;d=json.loads((r/'design.json').read_text());meta=[{k:v for k,v in s.items() if k!='nodes'} for s in d['screens']]
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>BIG BEN — полный дизайн</title><style>
*{box-sizing:border-box}body{margin:0;background:#eee9e2;color:#23211f;font:14px Arial,sans-serif}button,a{font:inherit}header{position:sticky;top:0;z-index:5;background:#242220;color:#fff;padding:15px 24px;display:flex;gap:22px;align-items:center}header strong{font:26px Georgia,serif;letter-spacing:2px}header span{color:#d1c4b8;font-size:12px}button{cursor:pointer;padding:10px 14px;border:1px solid #d1c4b8;border-radius:5px;background:transparent;color:inherit}button.active{background:#681e30;border-color:#681e30;color:white}nav{position:fixed;top:70px;bottom:0;width:250px;background:#faf8f5;border-right:1px solid #ded7cd;overflow:auto;padding:22px 15px}nav input{width:100%;padding:12px;border:1px solid #ded7cd;border-radius:4px;margin-bottom:15px}nav button{display:block;text-align:left;width:100%;border:0;color:#23211f;padding:10px 12px;margin-bottom:3px}nav button.active{color:#fff}main{margin-left:250px;padding:24px;min-height:100vh}.toolbar{display:flex;gap:10px;justify-content:space-between;align-items:center;margin-bottom:20px}.toolbar a{color:#681e30;font-weight:bold}.screen{display:block;margin:auto;background:white;box-shadow:0 12px 50px #24222017;max-width:100%;height:auto}#view.mobile .screen{max-width:390px}.board{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.board a{display:block;color:#23211f;text-decoration:none}.board img{display:block;width:100%;height:270px;object-fit:cover;object-position:top;background:white;border:1px solid #ded7cd;margin-bottom:10px}.note{font-size:12px;color:#77736e;line-height:1.6}h1{font:26px Georgia,serif;margin:0}#modal{display:none;position:fixed;inset:0;background:#0008;z-index:20;align-items:center;justify-content:center}#modal.open{display:flex}#modal article{background:#faf8f5;padding:30px;max-width:650px;line-height:1.7;margin:20px}#modal button{color:#681e30}@media(max-width:850px){nav{position:relative;top:0;width:auto;max-height:210px}main{margin:0;padding:12px}header{flex-wrap:wrap;padding:12px}.board{grid-template-columns:repeat(2,1fr)}header span{display:none}}
</style><header><strong>BIG BEN</strong><span>42 страницы · 84 экрана · концепция магазина</span><button id="desktop" class="active">Компьютер</button><button id="mobile">Телефон</button><button id="overview">Все страницы</button><button id="guide">В Figma</button></header><nav><input id="filter" placeholder="Найти страницу…" aria-label="Найти страницу"><div id="pages"></div></nav><main><div class="toolbar"><h1 id="title"></h1><a id="download" download>Скачать SVG</a></div><div id="view"></div><p class="note">Концепция: данные товаров, цены и контакты демонстрационные. Структуру действующего bigben65.ru не удалось подтвердить из-за 403. Макеты показывают все 42 предусмотренных типа страниц, включая дополнительные состояния.</p></main><div id="modal"><article><h2>Редактирование в Figma</h2><p>В Figma Desktop откройте новый файл. В меню Plugins → Development → Import plugin from manifest выберите <b>figma-plugin/manifest.json</b>. Запустите плагин BIG BEN Design Import, выберите устройства и нажмите «Создать экраны».</p><p>Плагин создаст настоящие Frame, Text, Rectangle и Vector: надписи и цвета можно менять. Сохраните файл через File → Save local copy, чтобы получить собственный .fig.</p><p>Можно также перетащить отдельные SVG из папки screens в Figma. Для редактируемого текста предпочтителен плагин.</p><button id="close-guide">Понятно</button></article></div><script>
const screens=__META__;let mobile=false,current='home',board=false;const view=document.querySelector('#view');
function render(){const items=screens.filter(s=>s.mobile===mobile);document.querySelector('#desktop').classList.toggle('active',!mobile);document.querySelector('#mobile').classList.toggle('active',mobile);view.className=mobile?'mobile':'';document.querySelector('#pages').innerHTML=items.filter(s=>s.title.toLowerCase().includes(document.querySelector('#filter').value.toLowerCase())).map(s=>`<button data-page="${s.slug}" class="${s.slug===current&&!board?'active':''}">${s.title}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{current=b.dataset.page;board=false;render();window.scrollTo(0,0)});if(board){document.querySelector('#title').textContent='Все страницы';document.querySelector('#download').style.display='none';view.innerHTML='<div class="board">'+items.map(s=>`<a href="#${s.slug}" data-go="${s.slug}"><img loading="lazy" src="screens/${s.id}.svg" alt="${s.title}">${s.title}</a>`).join('')+'</div>';document.querySelectorAll('[data-go]').forEach(a=>a.onclick=e=>{e.preventDefault();current=a.dataset.go;board=false;render();window.scrollTo(0,0)})}else{const s=items.find(s=>s.slug===current);document.querySelector('#title').textContent=s.title;document.querySelector('#download').style.display='';document.querySelector('#download').href=`screens/${s.id}.svg`;view.innerHTML=`<img class="screen" src="screens/${s.id}.svg" alt="Макет: ${s.title}">`;history.replaceState(null,'','#'+s.slug+(mobile?'-mobile':''))}}
document.querySelector('#desktop').onclick=()=>{mobile=false;render()};document.querySelector('#mobile').onclick=()=>{mobile=true;render()};document.querySelector('#overview').onclick=()=>{board=true;render()};document.querySelector('#filter').oninput=render;document.querySelector('#guide').onclick=()=>document.querySelector('#modal').classList.add('open');document.querySelector('#close-guide').onclick=()=>document.querySelector('#modal').classList.remove('open');const hash=location.hash.slice(1);if(hash){mobile=hash.endsWith('-mobile');current=hash.replace(/-mobile$/,'');if(!screens.some(s=>s.slug===current))current='home'}render();</script></html>'''
(r/'index.html').write_text(page.replace('__META__',json.dumps(meta,ensure_ascii=False)))
